import{H as e,ht as t,it as n,nt as r,tt as i,yt as a}from"./chunks/framework.BfsW3bkh.js";var o=JSON.parse(`{"title":"Encoding algorithms and implementations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operators.md","filePath":"guide/operators.md","lastUpdated":0}`),s={name:`guide/operators.md`};function c(e,o,s,c,l,u){let d=a(`VitePressMermaid`);return t(),i(`div`,null,[o[0]||=r(`<h1 id="encoding-operators" tabindex="-1">Encoding algorithms and implementations <a class="header-anchor" href="#encoding-operators" aria-label="Permalink to “Encoding algorithms and implementations”">​</a></h1><p>Two families implement the same physical signal model: <strong>Explicit</strong> evaluates the selected phase directly; <strong>LowRank</strong> approximates the residual phase while retaining the first-order Fourier terms in an NFFT.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Family</th><th style="text-align:left;">Public entry</th><th style="text-align:left;">Choices</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/explicit">Explicit</a></td><td style="text-align:left;"><code>HighOrderExplicitOp</code></td><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/explicit-array">Array</a>, CUDA acceleration: <a href="/HighOrderMRI.jl/dev/guide/explicit-kernel">Direct kernel</a> or <a href="/HighOrderMRI.jl/dev/guide/explicit-gemm">GEMM and phase-reuse</a></td></tr><tr><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/low-rank">LowRank</a></td><td style="text-align:left;"><code>HighOrderLowRankOp</code></td><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/per-readout">Per-readout</a>, <a href="/HighOrderMRI.jl/dev/guide/incremental-shared">Incremental Shared</a>, <a href="/HighOrderMRI.jl/dev/guide/direct-shared">Direct Shared</a></td></tr></tbody></table><p>Direct Shared has <a href="/HighOrderMRI.jl/dev/guide/direct-shared-per-readout">Per-readout</a> and <a href="/HighOrderMRI.jl/dev/guide/direct-shared-global">Global</a> strategies. These describe shared-basis construction and rank selection, independently of CUDA scheduling and FFT execution. The default LowRank method remains Incremental Shared.</p>`,4),n(d,{code:`flowchart%20TD%0A%20%20%20%20M%5B%22Common%20encoding%20model%22%5D%20--%3E%20E%5B%22Explicit%22%5D%0A%20%20%20%20M%20--%3E%20L%5B%22LowRank%22%5D%0A%20%20%20%20E%20--%3E%20A%5B%22Array%22%5D%0A%20%20%20%20E%20--%3E%20K%5B%22CUDA%20acceleration%22%5D%0A%20%20%20%20K%20--%3E%20D%5B%22Direct%20kernel%22%5D%0A%20%20%20%20K%20--%3E%20G%5B%22GEMM%20and%20phase-reuse%22%5D%0A%20%20%20%20L%20--%3E%20P%5B%22Per-readout%22%5D%0A%20%20%20%20L%20--%3E%20I%5B%22Incremental%20Shared%22%5D%0A%20%20%20%20L%20--%3E%20S%5B%22Direct%20Shared%22%5D%0A%20%20%20%20S%20--%3E%20R%5B%22Per-readout%20strategy%22%5D%0A%20%20%20%20S%20--%3E%20F%5B%22Global%20strategy%22%5D`}),o[1]||=r(`<h2 id="implementations" tabindex="-1">Method selection <a class="header-anchor" href="#implementations" aria-label="Permalink to “Method selection”">​</a></h2><div class="language-julia"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">explicit </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> HighOrderExplicitOp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(grid, kspha_matrix, times_vector;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    implementation</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, arrayType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Array)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">incremental </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> HighOrderLowRankOp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(grid, kspha, times;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    method</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:incremental_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, arrayType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Array)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">direct </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> HighOrderLowRankOp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(grid, kspha, times;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    method</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:direct_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, strategy</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, epsilon_H</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.01</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, arrayType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Array)</span></span></code></pre></div><p>These are construction patterns; supply the same measured fieldmap, CSM, mask and full data in a controlled comparison. They are not complete runnable data examples. The <a href="/HighOrderMRI.jl/dev/reference/highorderexplicitop">Explicit API</a> and <a href="/HighOrderMRI.jl/dev/reference/highorderlowrankop">LowRank API</a> contain complete CPU examples.</p><p>Use <code>HighOrderExplicitOp</code> for Explicit and <code>HighOrderLowRankOp</code> for LowRank. Explicit selects its implementation with <code>implementation</code>; LowRank selects its construction with <code>method</code> and <code>strategy</code>. Execution and solver settings are configured separately.</p><h2 id="common-inputs" tabindex="-1">Common inputs <a class="header-anchor" href="#common-inputs" aria-label="Permalink to “Common inputs”">​</a></h2><p>For a grid of size <code>(nX,nY,nZ)</code>:</p><ul><li><code>fieldmap</code>: <code>(nX,nY,nZ)</code>, or <code>(nX,nY)</code> when <code>nZ == 1</code>;</li><li><code>csm</code>: <code>(nX,nY,nZ,nCha)</code>, or <code>(nX,nY,nCha)</code> when <code>nZ == 1</code>;</li><li><code>mask</code>: the spatial grid shape;</li><li><code>k_nominal</code>: first-order coefficients ordered as <code>kx</code>, <code>ky</code>, <code>kz</code>;</li><li><code>recon_terms</code>: order-selection string defined in the <a href="./../theory/encoding-model#selecting-field-orders">expanded encoding model</a>;</li><li><code>concomitant</code>: optional integrated coefficients <code>(4,nSam)</code> for the explicit/single-dynamic operators or <code>(4,nSam,nDyn)</code> for dynamic LowRank, ordered as <code>z²</code>, <code>x²+y²</code>, <code>xz</code>, <code>yz</code>. Supply cycles/m² in the grid frame and origin; see <a href="/HighOrderMRI.jl/dev/theory/encoding-model#optional-concomitant-phase">concomitant phase</a>.</li></ul><p>The operator column count is always <code>prod(grid.matrixSize)</code>. A mask removes background voxels from the encoding calculation, while the adjoint restores unencoded voxels as zeros in the full image vector.</p><h2 id="coil-compression" tabindex="-1">Coil compression <a class="header-anchor" href="#coil-compression" aria-label="Permalink to “Coil compression”">​</a></h2><p>Both families and their existing concrete operators accept compressed data and compressed CSM through the same interface. Fit one <code>CoilCompressionTransform</code> and apply the same right-side transform to the data and sensitivity maps:</p><div class="language-julia"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data_cc, csm_cc, transform </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> compress_coils</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    data,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    csm;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    data_coil_dim</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    n_virtual_coils</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    noise_covariance,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">op </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> HighOrderExplicitOp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(grid, kspha, times; csm</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">csm_cc, arrayType</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Array)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">image </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> recon_HOOp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(op, data_cc, weights, rec_params)</span></span></code></pre></div><p>The same <code>csm_cc</code> can be supplied to <code>HighOrderExplicitOp</code> or <code>HighOrderLowRankOp</code>. Using one transform for both acquired signals and coil sensitivities preserves the transformed signal equation; independently fitted transforms generally do not.</p><p>For a noise-only matrix with samples in rows and coils in columns, estimate</p><div class="language-julia"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">noise_covariance </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> estimate_noise_covariance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(noise_data; coil_dim</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>before fitting the transform. Omitting the covariance corresponds to an independent, equal-variance noise model. The whitening and compression equations are given in <a href="/HighOrderMRI.jl/dev/guide/coil-compression">Coil compression</a>.</p><h2 id="highorderop-array-based-explicit-evaluation" tabindex="-1">Array-based explicit evaluation <a class="header-anchor" href="#highorderop-array-based-explicit-evaluation" aria-label="Permalink to “Array-based explicit evaluation”">​</a></h2><p>The former Array section is now <a href="/HighOrderMRI.jl/dev/guide/explicit-array">Explicit: Array</a>.</p><h2 id="highorderkernelop-explicit-cuda-evaluation" tabindex="-1">Direct kernel <a class="header-anchor" href="#highorderkernelop-explicit-cuda-evaluation" aria-label="Permalink to “Direct kernel”">​</a></h2><p>The former Kernel section is now <a href="/HighOrderMRI.jl/dev/guide/explicit-kernel">Direct kernel</a>.</p><h2 id="gpu-resident-explicit-reconstruction" tabindex="-1">GPU-resident explicit reconstruction <a class="header-anchor" href="#gpu-resident-explicit-reconstruction" aria-label="Permalink to “GPU-resident explicit reconstruction”">​</a></h2><p>Resident direct execution is described in <a href="/HighOrderMRI.jl/dev/guide/explicit-kernel">Direct kernel</a>; phase reuse, full caching, weights and memory accounting are in <a href="/HighOrderMRI.jl/dev/guide/explicit-gemm">GEMM and phase-reuse</a>.</p><h2 id="highorderlowrankop-shared-spatial-representation" tabindex="-1">Shared spatial representation <a class="header-anchor" href="#highorderlowrankop-shared-spatial-representation" aria-label="Permalink to “Shared spatial representation”">​</a></h2><p>See <a href="/HighOrderMRI.jl/dev/guide/incremental-shared">Incremental Shared</a> and <a href="/HighOrderMRI.jl/dev/guide/direct-shared">Direct Shared</a> for their different construction paths.</p><h3 id="independent-per-readout-factors" tabindex="-1">Independent per-readout factors <a class="header-anchor" href="#independent-per-readout-factors" aria-label="Permalink to “Independent per-readout factors”">​</a></h3><p>See <a href="/HighOrderMRI.jl/dev/guide/per-readout">Per-readout</a> for local factors, streaming and regeneration.</p><h3 id="automatic-joint-shared-basis" tabindex="-1">Direct shared construction <a class="header-anchor" href="#automatic-joint-shared-basis" aria-label="Permalink to “Direct shared construction”">​</a></h3><p>See <a href="/HighOrderMRI.jl/dev/guide/direct-shared">Direct Shared</a> for both strategies and fixed-rank controls.</p><h2 id="implementation-paths" tabindex="-1">Implementation paths <a class="header-anchor" href="#implementation-paths" aria-label="Permalink to “Implementation paths”">​</a></h2><p><code>HighOrderExplicitOp</code> is the Explicit family type and constructor. Its internal Array and CUDA implementations live in <code>EncodingOperator/Explicit/</code>. <code>HighOrderLowRankOp</code> handles construction and products for all LowRank methods; its factor and execution components live in <code>EncodingOperator/LowRank/</code>. Both families work with <code>recon_HOOp</code> and the documented normal and resource interfaces.</p><h2 id="numerical-consistency-checks" tabindex="-1">Numerical consistency checks <a class="header-anchor" href="#numerical-consistency-checks" aria-label="Permalink to “Numerical consistency checks”">​</a></h2><p>Compare random complex forward, adjoint and weighted-normal products against an independent phase reference. Preserve data, initial image, weights, normalization, regularization, precision and solver when comparing complete reconstructions. Use <a href="/HighOrderMRI.jl/dev/guide/validation">Scientific validation</a> for the full numerical/physical evidence hierarchy, and <a href="/HighOrderMRI.jl/dev/guide/multi-gpu">execution</a> and <a href="/HighOrderMRI.jl/dev/reference/resources">resources</a> for device scheduling and cleanup.</p>`,31)])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};